package io.invenlio.warehouse;import jakarta.servlet.http.*;import java.net.*;import java.util.*;import org.slf4j.MDC;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;
@RestControllerAdvice class WarehouseExceptionHandler{@ExceptionHandler(WarehouseException.class)ResponseEntity<ProblemDetail> handle(WarehouseException e,HttpServletRequest r){var conflicts=Set.of("WAREHOUSE_CODE_EXISTS","ZONE_CODE_EXISTS","LOCATION_CODE_EXISTS","LOCATION_SCAN_CODE_EXISTS","CONCURRENT_MODIFICATION");var status=e.code().endsWith("NOT_FOUND")?HttpStatus.NOT_FOUND:conflicts.contains(e.code())?HttpStatus.CONFLICT:HttpStatus.BAD_REQUEST;var p=ProblemDetail.forStatusAndDetail(status,e.getMessage());p.setType(URI.create("https://invenlio.io/problems/"+e.code().toLowerCase().replace('_','-')));p.setTitle(status.getReasonPhrase());p.setInstance(URI.create(r.getRequestURI()));p.setProperty("code",e.code());p.setProperty("correlationId",MDC.get("correlationId"));return ResponseEntity.status(status).contentType(MediaType.APPLICATION_PROBLEM_JSON).body(p);}}
